// HSK 7–9 高等场景课程。官方大纲将 7–9 级作为同一个高级段；本文件不再拆分单级。
// 对话、说明、例句和练习均为青禾中文原创，主题与能力任务依据 HSK 3.0（2025 大纲）映射。
const advancedLessons=[
  makeUpperLesson({id:'QH-061',level:'HSK 7–9',title:'面对网络谣言，先核实再转发',scene:'分析媒介信息与公共责任',vocab:['媒介','素养','澄清','谣言','版权','诽谤','辨别'],dialogue:['林|这条消息已经被很多账号转发，应该是真的吧？','安|传播范围大并不代表内容可靠，首先要辨别来源。','林|如果后来证明是谣言，删掉就可以了吗？','安|还要及时澄清；涉及诽谤或侵犯版权时，发布者也可能承担责任。','林|所谓媒介素养，就是在转发之前核实证据和语境。'],grammar:{name:'所谓……，就是……',pattern:'所谓 + 概念，就是 + 准确定义或解释',explain:'用于对一个概念作出界定，适合说明、评论和学术性表达。',examples:['所谓媒介素养，就是判断信息来源与证据的能力。','所谓负责，并不是不犯错，而是愿意纠正错误。'],wrong:'所谓媒介素养，所以核实来源。'},listening:{q:'安认为消息被大量转发能证明真实吗？',audio:'传播范围大并不代表内容可靠，首先要辨别来源。',opts:['可以直接证明','不能直接证明','只要朋友转发就能证明'],ans:1},shadowing:'所谓媒介素养，就是在转发之前核实信息的来源、证据和语境。',quiz:{q:'所谓数字素养，___ 能够安全、有效地使用数字工具。',opts:['就是','即使','以免'],ans:0,fb:'对概念作定义时，用“所谓……就是……”。'}}),
  makeUpperLesson({id:'QH-062',level:'HSK 7–9',title:'算法推荐是否应该更透明',scene:'讨论人工智能伦理与监管',vocab:['算法','偏见','伦理','监管','透明','滥用','追责'],dialogue:['安|推荐算法很方便，为什么还有人要求平台公开更多信息？','林|因为算法可能放大已有偏见，用户却不知道内容为何出现。','安|那是不是应该公开全部技术细节？','林|虽说商业秘密需要保护，但影响公共利益的规则仍应足够透明。','安|一旦技术被滥用，也要有清楚的监管和追责机制。'],grammar:{name:'虽说……，但/可……',pattern:'虽说 + 承认的情况，但/可 + 主要判断',explain:'先承认一种事实，再提出更重要或不同方向的判断，语气比“虽然”更具讨论感。',examples:['虽说技术带来便利，但它也可能放大偏见。','虽说时间有限，可关键问题不能回避。'],wrong:'虽说技术便利，所以但是没有风险。'},listening:{q:'林为什么认为算法需要更透明？',audio:'算法可能放大已有偏见，用户却不知道内容为何出现。',opts:['为了公开所有商业秘密','因为它会影响用户并可能放大偏见','为了减少技术研究'],ans:1},shadowing:'虽说商业秘密需要保护，但影响公共利益的算法规则仍应足够透明。',quiz:{q:'虽说时间有限，___ 关键问题不能回避。',opts:['但','因此也许','所以却'],ans:0,fb:'承认前项后转入主要判断，用“但”衔接。'}}),
  makeUpperLesson({id:'QH-063',level:'HSK 7–9',title:'老龄化社区需要怎样的公共服务',scene:'评价基层治理与养老保障',vocab:['老龄化','养老','保障','基层','治理','配套','缺口'],dialogue:['林|这个社区的老年人口比例越来越高，最需要增加什么服务？','安|养老服务不只是多建活动室，还包括医疗、助餐和紧急响应。','林|资金有限，所有设施都要一次建好吗？','安|无论条件是否充足，都应先识别最紧迫的保障缺口。','林|基层治理要让居民参与，配套服务才会真正符合需要。'],grammar:{name:'无论……与否，都……',pattern:'无论 + 情况 + 与否，都 + 不变的原则或结果',explain:'表示前项出现或不出现，都不改变后项结论，常用于正式论述。',examples:['无论资源充足与否，都要先保障基本需求。','无论申请成功与否，都请及时告知结果。'],wrong:'无论资源充足与否，但是先保障需求。'},listening:{q:'安认为应当先做什么？',audio:'无论条件是否充足，都应先识别最紧迫的保障缺口。',opts:['一次建完所有设施','先识别最紧迫的缺口','只建设活动室'],ans:1},shadowing:'无论资源充足与否，基层治理都应优先保障最基本、最紧迫的养老需求。',quiz:{q:'无论申请成功 ___ ，都请及时告知结果。',opts:['与否','而且','所以'],ans:0,fb:'正式表达两种可能时可用“与否”。'}}),
  makeUpperLesson({id:'QH-064',level:'HSK 7–9',title:'绿色转型不能忽略谁的代价',scene:'论证生态保护与社会发展',vocab:['碳排放','生态','可持续','能源','转型','兼顾','代价'],dialogue:['安|减少碳排放就意味着立刻关闭所有传统能源项目吗？','林|绿色转型需要方向明确，也要考虑不同地区的现实条件。','安|为什么还要设置过渡期？','林|一来要保证能源供应，二来要帮助相关劳动者完成职业转型。','安|可持续发展应该兼顾生态目标和不同群体承担的代价。'],grammar:{name:'一来……，二来……',pattern:'一来 + 理由一，二来 + 理由二',explain:'按顺序列举两项主要理由，使论证结构更清楚。',examples:['一来要保障供应，二来要降低转型成本。','选择公共交通，一来省钱，二来减少排放。'],wrong:'一来要保障供应，但是二来所以转型。'},listening:{q:'为什么需要设置绿色转型的过渡期？',audio:'一来要保证能源供应，二来要帮助相关劳动者完成职业转型。',opts:['为了增加碳排放','为了兼顾供应和劳动者转型','为了停止发展新能源'],ans:1},shadowing:'绿色转型一来要实现生态目标，二来要兼顾不同群体承担的社会代价。',quiz:{q:'选择公共交通，一来省钱，___ 减少排放。',opts:['二来','否则','纵然'],ans:0,fb:'列举第二项理由时用“二来”。'}}),
  makeUpperLesson({id:'QH-065',level:'HSK 7–9',title:'诊疗决定不只是技术问题',scene:'讨论医疗沟通与医学伦理',vocab:['诊疗','病患','医学伦理','疗效','诊断','隐私','争议'],dialogue:['林|新疗法的初步疗效不错，为什么还不能马上推广？','安|诊疗决定不仅看技术效果，还要评估风险和病患意愿。','林|如果家属要求隐瞒诊断结果呢？','安|具体做法要结合病患状态与法律规范，但隐私和知情权不能被忽略。','林|医学伦理的争议往往没有简单答案，需要充分沟通。'],grammar:{name:'不仅……，还要……',pattern:'不仅 + 一个判断，还要 + 进一步的要求',explain:'在已有判断上补充更高层次的要求，适合组织多因素论证。',examples:['诊疗决定不仅看疗效，还要评估风险。','研究不仅要有创新，还要遵守伦理规范。'],wrong:'不仅看疗效，但是还要所以风险。'},listening:{q:'安认为诊疗决定还要考虑哪些因素？',audio:'诊疗决定不仅看技术效果，还要评估风险和病患意愿。',opts:['只看技术效果','风险和病患意愿','只听家属意见'],ans:1},shadowing:'诊疗决定不仅要评估疗效，还要尊重病患的隐私、意愿和知情权。',quiz:{q:'研究不仅要有创新，___ 遵守伦理规范。',opts:['还要','反倒不','从而只'],ans:0,fb:'在前项基础上补充要求，用“还要”。'}}),
  makeUpperLesson({id:'QH-066',level:'HSK 7–9',title:'文化遗产是保存还是活化',scene:'评价文化遗产保护与传承',vocab:['文化遗产','传承','非物质文化遗产','修复','原貌','活化','认同'],dialogue:['安|古建筑修复得越新，是不是保护得越好？','林|未必。修复首先要尊重材料、工艺和历史信息。','安|那文化遗产只能保存原貌，不能用于现代生活吗？','林|保护并非让遗产停止变化，而是让活化利用不破坏核心价值。','安|当社区重新参与传承时，文化认同也会变得更具体。'],grammar:{name:'并非……，而是……',pattern:'并非 + 被否定的理解，而是 + 更准确的解释',explain:'纠正一个片面理解，并把重点转移到更准确的判断上。',examples:['保护并非拒绝变化，而是避免核心价值被破坏。','传承并非简单复制，而是让文化继续产生意义。'],wrong:'保护并非拒绝变化，所以而是核心价值。'},listening:{q:'林怎样理解文化遗产的活化？',audio:'保护并非让遗产停止变化，而是让活化利用不破坏核心价值。',opts:['把遗产完全封闭','在不破坏核心价值的前提下使用','把建筑全部翻新'],ans:1},shadowing:'文化遗产保护并非让历史停止变化，而是让传承与活化守住核心价值。',quiz:{q:'传承并非简单复制，___ 让文化继续产生意义。',opts:['而是','即便','免得'],ans:0,fb:'纠正理解并突出真正重点，用“而是”。'}}),
  makeUpperLesson({id:'QH-067',level:'HSK 7–9',title:'相关性不等于因果关系',scene:'解读研究数据与市场报告',vocab:['样本','变量','相关性','因果','偏差','推断','显著'],dialogue:['林|报告发现学习时间与成绩显著相关，能说明多学就一定提高吗？','安|还不能。相关性可能受其他变量影响，不能直接当作因果。','林|那这份研究还有什么限制？','安|样本只来自一所学校，选择偏差会影响推断范围。','林|换句话说，数据支持一种可能，但结论仍需更多证据验证。'],grammar:{name:'换句话说',pattern:'陈述较复杂内容。换句话说，+ 更清楚的概括',explain:'用另一种说法解释或概括前文，帮助听者把握核心结论。',examples:['相关不等于因果。换句话说，两者同时变化不一定互相造成。','样本范围有限。换句话说，结论不能随意推广。'],wrong:'换句话说因为样本，所以但是结论。'},listening:{q:'为什么不能把相关性直接当作因果？',audio:'相关性可能受其他变量影响，不能直接当作因果。',opts:['因为没有任何数据','因为可能受到其他变量影响','因为样本越大越不可信'],ans:1},shadowing:'相关性不等于因果；换句话说，两个变量同时变化不代表它们互相造成。',quiz:{q:'样本只来自一所学校。___ ，结论不能随意推广。',opts:['换句话说','一经','以至于'],ans:0,fb:'用更清楚的说法概括前文，可用“换句话说”。'}}),
  makeUpperLesson({id:'QH-068',level:'HSK 7–9',title:'合作协议里的责任边界',scene:'开展业务洽谈与风险协商',vocab:['洽谈','条款','履约','分成','担保','风险','违约'],dialogue:['安|对方接受了收益分成，却不愿承担交付延误的风险。','林|那就要在洽谈时把履约标准和违约责任写进条款。','安|他们希望我们提供额外担保，应该答应吗？','林|要视风险分配而定，不能只看眼前的合作机会。','安|本着权责一致的原则，双方都应明确能够承担的边界。'],grammar:{name:'本着……的原则',pattern:'本着 + 原则/态度 + 采取行动',explain:'说明行动所依据的价值或原则，常见于正式协商、声明和公文。',examples:['本着权责一致的原则，双方应明确风险边界。','本着实事求是的态度，我们重新核对了数据。'],wrong:'本着权责一致，所以的原则协商。'},listening:{q:'林建议把哪些内容写进合同条款？',audio:'要在洽谈时把履约标准和违约责任写进条款。',opts:['只写收益分成','履约标准和违约责任','不写任何风险'],ans:1},shadowing:'本着权责一致的原则，合作双方应在洽谈中明确履约标准和违约责任。',quiz:{q:'本着实事求是的 ___ ，我们重新核对了数据。',opts:['态度','程度','角度着'],ans:0,fb:'“本着”后常接“原则、态度、精神”等依据。'}}),
  makeUpperLesson({id:'QH-069',level:'HSK 7–9',title:'怎样写一篇研究综述',scene:'整合文献并建立学术论证',vocab:['研究综述','文献','引用','论证','框架','假设','结论'],dialogue:['林|我已经读了很多文献，可写出来还是像资料清单。','安|研究综述不能只逐篇介绍，还要围绕问题建立分析框架。','林|是不是先比较不同研究的假设、证据和结论？','安|对，同时要准确引用，说明观点之间的联系与分歧。','林|综上所述，综述的价值在于整合已有研究并指出新的问题。'],grammar:{name:'综上所述',pattern:'梳理多项信息后，综上所述，+ 总结性结论',explain:'用于正式书面语或陈述结尾，对前文论证作整体概括。',examples:['综上所述，现有证据仍不足以支持该假设。','综上所述，这些研究在方法与结论上都存在差异。'],wrong:'综上所述因为证据，所以然而结论。'},listening:{q:'研究综述为什么不能只是资料清单？',audio:'研究综述不能只逐篇介绍，还要围绕问题建立分析框架。',opts:['因为文献越少越好','因为还要建立分析框架并比较研究','因为不能引用任何资料'],ans:1},shadowing:'综上所述，研究综述需要整合文献、比较论证，并在已有结论中发现新问题。',quiz:{q:'___ ，现有证据仍不足以支持该假设。',opts:['综上所述','动不动就','一经'],ans:0,fb:'概括前文并引出总判断，用“综上所述”。'}}),
  makeUpperLesson({id:'QH-070',level:'HSK 7–9',title:'翻译要忠实，也要得体',scene:'处理跨文化语境与礼仪差异',vocab:['语境','隐含','得体','直译','意译','礼仪','分寸'],dialogue:['安|这句祝福直译没有错，为什么听起来还是有点奇怪？','林|翻译不只转换字面意思，还要理解语境和隐含态度。','安|那什么时候适合意译？','林|要视交际目的和文化礼仪而定，但不能随意改变原意。','安|真正得体的翻译，需要在忠实和表达分寸之间做判断。'],grammar:{name:'视……而定',pattern:'结果/做法 + 视 + 条件 + 而定',explain:'表示没有单一答案，具体决定取决于某个条件，常用于正式分析。',examples:['翻译策略要视语境而定。','会议形式视参与人数而定。'],wrong:'翻译策略视语境所以而定了。'},listening:{q:'林认为意译的选择取决于什么？',audio:'要视交际目的和文化礼仪而定，但不能随意改变原意。',opts:['只取决于句子长度','取决于交际目的和文化礼仪','可以完全改变原意'],ans:1},shadowing:'翻译策略要视语境而定，既要忠实传达原意，也要保持表达得体。',quiz:{q:'会议形式视参与人数 ___ 。',opts:['而定','以至','罢了'],ans:0,fb:'表示由条件决定，用“视……而定”。'}})
];

lessons.push(...advancedLessons);
